**Design note (data structures & complexity):**
- Core: a single sorted `list[tuple[int,int]]` of normalized (disjoint, non-touching, non-empty) half-open intervals; ends are also monotonically increasing, enabling `bisect` on both coordinates.
- Lookups (`contains`, `overlaps`, `covers`): one `bisect` call → O(log n).
- Mutations (`add`, `remove`): two `bisect` calls to locate the affected slice, then a single `list.__setitem__` (C-level memmove) on that slice → O(log n + k).
- Set ops (`union`, `intersection`, `difference`): linear merge of two sorted lists, O((n+m) log(n+m)) for union (sort), O(n+m) for intersection/difference.
- Validation is strict: reject `bool`, non-`int`, and `start > end`; mutate state only after all checks pass.
- Concurrency: none (documented as not thread-safe; single-threaded use assumed).

### solution.py

```python
"""IntervalSet – mutable, normalized set of half-open integer intervals [start, end)."""

from __future__ import annotations

import bisect
from typing import Iterable


class IntervalSet:
    """A mutable set of half-open integer intervals, kept normalized.

    Intervals are stored as a sorted list of disjoint, non-touching,
    non-empty [start, end) pairs.  The class is **not** hashable
    (it is mutable) and is **not** thread-safe.
    """

    __hash__: None = None  # type: ignore[assignment]

    # ---- construction ------------------------------------------------

    def __init__(self, intervals: Iterable[tuple[int, int]] | None = None) -> None:
        self._intervals: list[tuple[int, int]] = []
        if intervals is not None:
            for start, end in intervals:
                self.add(start, end)

    # ---- helpers -----------------------------------------------------

    @staticmethod
    def _check_int(x: object, name: str = "coordinate") -> int:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError(
                f"{name} must be an int, got {type(x).__name__}"
            )
        return x

    @classmethod
    def _check_range(cls, start: object, end: object) -> tuple[int, int]:
        s = cls._check_int(start, "start")
        e = cls._check_int(end, "end")
        if s > e:
            raise ValueError(f"start ({s}) > end ({e})")
        return s, e

    # ---- mutation ----------------------------------------------------

    def add(self, start: int, end: int) -> None:
        s, e = self._check_range(start, end)
        if s == e:
            return
        iv = self._intervals

        # right_bound: first index with start > e  (all iv[0:rb] have start <= e)
        right_bound = bisect.bisect_right(iv, (e, float("inf")))

        # left_bound: first index with start >= s
        left_bound = bisect.bisect_left(iv, (s,))
        # The interval at left_bound-1 may touch/overlap (its end >= s)
        if left_bound > 0 and iv[left_bound - 1][1] >= s:
            left_bound -= 1

        if left_bound >= right_bound:
            # No touching/overlapping interval – pure insertion
            iv.insert(left_bound, (s, e))
        else:
            new_s = min(s, iv[left_bound][0])
            new_e = max(e, iv[right_bound - 1][1])
            iv[left_bound:right_bound] = [(new_s, new_e)]

    def remove(self, start: int, end: int) -> None:
        s, e = self._check_range(start, end)
        if s == e:
            return
        iv = self._intervals

        # right_bound: first index with start >= e (all iv[0:rb] have start < e)
        right_bound = bisect.bisect_left(iv, (e,))

        # left_bound: first index with start >= s
        left_bound = bisect.bisect_left(iv, (s,))
        # Check left_bound-1 for overlap (end > s)
        if left_bound > 0 and iv[left_bound - 1][1] > s:
            left_bound -= 1

        if left_bound >= right_bound:
            return  # nothing overlaps [s, e)

        # Build remaining pieces
        new_parts: list[tuple[int, int]] = []
        for iv_s, iv_e in iv[left_bound:right_bound]:
            if iv_s < s:
                new_parts.append((iv_s, s))
            if iv_e > e:
                new_parts.append((e, iv_e))
        iv[left_bound:right_bound] = new_parts

    # ---- queries -----------------------------------------------------

    def contains(self, x: int) -> bool:
        self._check_int(x)
        iv = self._intervals
        # rightmost interval with start <= x
        i = bisect.bisect_right(iv, (x, float("inf"))) - 1
        if i < 0:
            return False
        return iv[i][0] <= x < iv[i][1]

    def overlaps(self, start: int, end: int) -> bool:
        s, e = self._check_range(start, end)
        if s == e:
            return False
        iv = self._intervals
        # Find first interval with start >= e  →  all iv[0:rb] have start < e
        rb = bisect.bisect_left(iv, (e,))
        if rb == 0:
            return False
        # iv[rb-1] has start < e; does it extend past s?
        return iv[rb - 1][1] > s

    def covers(self, start: int, end: int) -> bool:
        s, e = self._check_range(start, end)
        if s == e:
            return True  # vacuously
        iv = self._intervals
        i = bisect.bisect_right(iv, (s, float("inf"))) - 1
        if i < 0:
            return False
        iv_s, iv_e = iv[i]
        return iv_s <= s and iv_e >= e

    def gaps(self, start: int, end: int) -> list[tuple[int, int]]:
        s, e = self._check_range(start, end)
        if s == e:
            return []
        iv = self._intervals

        # leftmost relevant: first with end > s
        left = bisect.bisect_left(iv, (s,))
        if left > 0 and iv[left - 1][1] > s:
            left -= 1
        # rightmost relevant: last with start < e → index = bisect_left(iv, (e,))
        right = bisect.bisect_left(iv, (e,))

        result: list[tuple[int, int]] = []
        prev = s
        for k in range(left, right):
            iv_s, iv_e = iv[k]
            if iv_s > prev:
                result.append((prev, min(iv_s, e)))
            prev = max(prev, iv_e)
        if prev < e:
            result.append((prev, e))
        return result

    def total_length(self) -> int:
        return sum(e - s for s, e in self._intervals)

    # ---- copy / set operations ---------------------------------------

    def copy(self) -> IntervalSet:
        new = IntervalSet.__new__(IntervalSet)
        new._intervals = list(self._intervals)
        return new

    def union(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(
                f"union requires IntervalSet, got {type(other).__name__}"
            )
        merged = self._intervals + other._intervals
        merged.sort()
        result: list[tuple[int, int]] = []
        for s, e in merged:
            if result and s <= result[-1][1]:
                result[-1] = (result[-1][0], max(result[-1][1], e))
            else:
                result.append((s, e))
        out = IntervalSet.__new__(IntervalSet)
        out._intervals = result
        return out

    def intersection(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(
                f"intersection requires IntervalSet, got {type(other).__name__}"
            )
        a, b = self._intervals, other._intervals
        result: list[tuple[int, int]] = []
        i = j = 0
        while i < len(a) and j < len(b):
            s = max(a[i][0], b[j][0])
            e = min(a[i][1], b[j][1])
            if s < e:
                result.append((s, e))
            if a[i][1] <= b[j][1]:
                i += 1
            else:
                j += 1
        out = IntervalSet.__new__(IntervalSet)
        out._intervals = result
        return out

    def difference(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(
                f"difference requires IntervalSet, got {type(other).__name__}"
            )
        b = other._intervals
        result: list[tuple[int, int]] = []
        for s, e in self._intervals:
            # gaps of b within [s, e)
            left = bisect.bisect_left(b, (s,))
            if left > 0 and b[left - 1][1] > s:
                left -= 1
            right = bisect.bisect_left(b, (e,))
            prev = s
            for k in range(left, right):
                bs, be = b[k]
                if bs > prev:
                    result.append((prev, bs))
                prev = max(prev, be)
            if prev < e:
                result.append((prev, e))
        out = IntervalSet.__new__(IntervalSet)
        out._intervals = result
        return out

    # ---- operators ---------------------------------------------------

    def __or__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.union(other)

    def __and__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.intersection(other)

    def __sub__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.difference(other)

    # ---- protocol ----------------------------------------------------

    def __iter__(self):
        yield from self._intervals

    def __len__(self) -> int:
        return len(self._intervals)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self._intervals == other._intervals

    def __repr__(self) -> str:
        return f"IntervalSet({self._intervals!r})"
```

### test_solution.py

```python
"""Comprehensive tests for the IntervalSet module."""

import pytest
import solution
from solution import IntervalSet


# ---- helpers -----------------------------------------------------------

def _sorted_iv(iv: list[tuple[int, int]]) -> list[tuple[int, int]]:
    return sorted(iv)


# ---- constructor & add ------------------------------------------------

class TestConstructor:
    def test_empty(self):
        s = IntervalSet()
        assert len(s) == 0
        assert s.total_length() == 0
        assert list(s) == []

    def test_from_pairs(self):
        s = IntervalSet([(3, 7), (1, 4), (8, 9)])
        # [1,4) and [3,7) merge → [1,7); [8,9) stays
        assert list(s) == [(1, 7), (8, 9)]

    def test_from_generator(self):
        s = IntervalSet((x, x + 1) for x in range(5))
        assert list(s) == [(0, 5)]

    def test_from_empty_iterable(self):
        s = IntervalSet([])
        assert len(s) == 0


class TestValidation:
    def test_float_start(self):
        with pytest.raises(TypeError):
            IntervalSet().add(1.0, 5)

    def test_float_end(self):
        with pytest.raises(TypeError):
            IntervalSet().add(1, 5.0)

    def test_bool_start(self):
        with pytest.raises(TypeError):
            IntervalSet().add(True, 5)

    def test_bool_end(self):
        with pytest.raises(TypeError):
            IntervalSet().add(1, False)

    def test_none_start(self):
        with pytest.raises(TypeError):
            IntervalSet().add(None, 5)

    def test_string_end(self):
        with pytest.raises(TypeError):
            IntervalSet().add(1, "5")

    def test_start_gt_end(self):
        with pytest.raises(ValueError):
            IntervalSet().add(10, 3)

    def test_validation_no_mutation(self):
        s = IntervalSet([(0, 10)])
        with pytest.raises(TypeError):
            s.add(1.5, 20)
        assert list(s) == [(0, 10)]

    def test_start_gt_end_no_mutation(self):
        s = IntervalSet([(0, 10)])
        with pytest.raises(ValueError):
            s.add(20, 5)
        assert list(s) == [(0, 10)]

    def test_constructor_bad_type(self):
        with pytest.raises(TypeError):
            IntervalSet([(1, 2), (3, 4.0)])

    def test_constructor_bad_range(self):
        with pytest.raises(ValueError):
            IntervalSet([(1, 2), (5, 3)])

    def test_contains_bad_type(self):
        with pytest.raises(TypeError):
            IntervalSet().contains(1.5)

    def test_contains_bool(self):
        with pytest.raises(TypeError):
            IntervalSet().contains(True)

    def test_negative_coords(self):
        s = IntervalSet()
        s.add(-10, -5)
        assert list(s) == [(-10, -5)]
        assert s.contains(-7)
        assert not s.contains(-5)

    def test_large_coords(self):
        s = IntervalSet()
        s.add(0, 10**18)
        assert s.contains(10**18 - 1)
        assert not s.contains(10**18)


# ---- add ---------------------------------------------------------------

class TestAdd:
    def test_empty_range(self):
        s = IntervalSet()
        s.add(5, 5)
        assert len(s) == 0

    def test_single(self):
        s = IntervalSet()
        s.add(1, 5)
        assert list(s) == [(1, 5)]
        assert s.total_length() == 4

    def test_merge_touching_right(self):
        s = IntervalSet([(1, 3)])
        s.add(3, 5)
        assert list(s) == [(1, 5)]

    def test_merge_touching_left(self):
        s = IntervalSet([(3, 5)])
        s.add(1, 3)
        assert list(s) == [(1, 5)]

    def test_merge_overlapping(self):
        s = IntervalSet([(1, 4), (6, 9)])
        s.add(3, 7)
        assert list(s) == [(1, 9)]

    def test_merge_many(self):
        s = IntervalSet([(0, 2), (4, 6), (8, 10), (12, 14)])
        s.add(1, 13)
        assert list(s) == [(0, 14)]

    def test_no_merge_gap(self):
        s = IntervalSet([(0, 2), (5, 7)])
        s.add(3, 4)
        assert list(s) == [(0, 2), (3, 4), (5, 7)]

    def test_add_inside(self):
        s = IntervalSet([(0, 10)])
        s.add(3, 5)
        assert list(s) == [(0, 10)]

    def test_add_extending(self):
        s = IntervalSet([(3, 7)])
        s.add(1, 9)
        assert list(s) == [(1, 9)]

    def test_duplicate_add(self):
        s = IntervalSet([(1, 5)])
        s.add(1, 5)
        assert list(s) == [(1, 5)]


# ---- remove ------------------------------------------------------------

class TestRemove:
    def test_empty_range(self):
        s = IntervalSet([(0, 10)])
        s.remove(3, 3)
        assert list(s) == [(0, 10)]

    def test_remove_exact(self):
        s = IntervalSet([(1, 5)])
        s.remove(1, 5)
        assert list(s) == []

    def test_remove_prefix(self):
        s = IntervalSet([(1, 10)])
        s.remove(1, 4)
        assert list(s) == [(4, 10)]

    def test_remove_suffix(self):
        s = IntervalSet([(1, 10)])
        s.remove(6, 10)
        assert list(s) == [(1, 6)]

    def test_remove_middle_splits(self):
        s = IntervalSet([(0, 10)])
        s.remove(3, 5)
        assert list(s) == [(0, 3), (5, 10)]

    def test_remove_no_overlap(self):
        s = IntervalSet([(0, 10)])
        s.remove(20, 30)
        assert list(s) == [(0, 10)]

    def test_remove_partial_multiple(self):
        s = IntervalSet([(0, 5), (7, 12), (14, 20)])
        s.remove(3, 9)
        assert list(s) == [(0, 3), (9, 12), (14, 20)]

    def test_remove_all(self):
        s = IntervalSet([(0, 5), (7, 12)])
        s.remove(0, 20)
        assert list(s) == []

    def test_remove_touching_not_overlapping(self):
        s = IntervalSet([(0, 5)])
        s.remove(5, 8)  # touching, not overlapping
        assert list(s) == [(0, 5)]


# ---- contains / overlaps / covers --------------------------------------

class TestQueries:
    def test_contains(self):
        s = IntervalSet([(2, 5), (8, 10)])
        assert s.contains(2)
        assert s.contains(4)
        assert not s.contains(5)  # half-open
        assert s.contains(8)
        assert not s.contains(10)
        assert not s.contains(6)

    def test_overlaps_basic(self):
        s = IntervalSet([(0, 5)])
        assert s.overlaps(3, 7)
        assert s.overlaps(0, 5)
        assert not s.overlaps(5, 8)  # touching, not overlapping
        assert not s.overlaps(6, 8)

    def test_overlaps_empty(self):
        s = IntervalSet([(0, 5)])
        assert not s.overlaps(3, 3)

    def test_overlaps_empty_set(self):
        assert not IntervalSet().overlaps(0, 10)

    def test_covers_basic(self):
        s = IntervalSet([(0, 10)])
        assert s.covers(0, 10)
        assert s.covers(2, 8)
        assert not s.covers(0, 11)
        assert not s.covers(5, 11)

    def test_covers_empty(self):
        assert IntervalSet().covers(5, 5)  # vacuously true

    def test_covers_multiple(self):
        s = IntervalSet([(0, 5), (7, 10)])
        assert not s.covers(0, 10)  # gap at [5,7)
        assert s.covers(0, 5)
        assert s.covers(7, 10)

    def test_covers_single_point(self):
        s = IntervalSet([(5, 6)])
        assert s.covers(5, 6)
        assert not s.covers(5, 7)


# ---- gaps --------------------------------------------------------------

class TestGaps:
    def test_basic(self):
        s = IntervalSet([(2, 4), (6, 8)])
        assert s.gaps(0, 10) == [(0, 2), (4, 6), (8, 10)]

    def test_window_inside(self):
        s = IntervalSet([(2, 4), (6, 8)])
        assert s.gaps(3, 7) == [(4, 6)]

    def test_window_all_covered(self):
        s = IntervalSet([(0, 10)])
        assert s.gaps(2, 8) == []

    def test_window_all_gaps(self):
        s = IntervalSet([(2, 4)])
        assert s.gaps(5, 8) == [(5, 8)]

    def test_empty_window(self):
        s = IntervalSet([(0, 10)])
        assert s.gaps(5, 5) == []

    def test_empty_set(self):
        assert IntervalSet().gaps(0, 5) == [(0, 5)]

    def test_exact_boundary(self):
        s = IntervalSet([(0, 5)])
        assert s.gaps(5, 10) == [(5, 10)]
        assert s.gaps(0, 5) == []


# ---- total_length / len / iter ----------------------------------------

class TestMetrics:
    def test_total_length(self):
        s = IntervalSet([(0, 5), (10, 13)])
        assert s.total_length() == 8

    def test_total_length_empty(self):
        assert IntervalSet().total_length() == 0

    def test_len_counts_intervals(self):
        s = IntervalSet([(0, 100)])
        assert len(s) == 1  # 1 interval, not 100 integers

    def test_len_empty(self):
        assert len(IntervalSet()) == 0

    def test_iter(self):
        s = IntervalSet([(5, 7), (1, 3)])
        assert list(s) == [(1, 3), (5, 7)]

    def test_iter_order(self):
        s = IntervalSet()
        s.add(10, 12)
        s.add(1, 3)
        s.add(5, 7)
        assert list(s) == [(1, 3), (5, 7), (10, 12)]

    def test_falsy_empty(self):
        assert not IntervalSet()
        assert bool(IntervalSet([(1, 2)]))


# ---- copy --------------------------------------------------------------

class TestCopy:
    def test_independent(self):
        s = IntervalSet([(1, 5)])
        c = s.copy()
        c.add(10, 15)
        assert list(s) == [(1, 5)]
        assert list(c) == [(1, 5), (10, 15)]

    def test_copy_equal(self):
        s = IntervalSet([(1, 5), (7, 9)])
        assert s == s.copy()


# ---- set operations ----------------------------------------------------

class TestUnion:
    def test_basic(self):
        a = IntervalSet([(1, 5)])
        b = IntervalSet([(4, 8)])
        assert list(a.union(b)) == [(1, 8)]

    def test_disjoint(self):
        a = IntervalSet([(1, 3)])
        b = IntervalSet([(7, 9)])
        assert list(a.union(b)) == [(1, 3), (7, 9)]

    def test_with_empty(self):
        a = IntervalSet([(1, 5)])
        assert list(a.union(IntervalSet())) == [(1, 5)]

    def test_not_modified(self):
        a = IntervalSet([(1, 5)])
        b = IntervalSet([(3, 8)])
        _ = a | b
        assert list(a) == [(1, 5)]
        assert list(b) == [(3, 8)]

    def test_operator(self):
        a = IntervalSet([(1, 5)])
        b = IntervalSet([(5, 9)])
        assert list(a | b) == [(1, 9)]


class TestIntersection:
    def test_basic(self):
        a = IntervalSet([(1, 10)])
        b = IntervalSet([(5, 15)])
        assert list(a.intersection(b)) == [(5, 10)]

    def test_no_overlap(self):
        a = IntervalSet([(1, 3)])
        b = IntervalSet([(5, 7)])
        assert list(a.intersection(b)) == []

    def test_contained(self):
        a = IntervalSet([(0, 100)])
        b = IntervalSet([(10, 20), (30, 40)])
        assert list(a & b) == [(10, 20), (30, 40)]

    def test_with_empty(self):
        assert list(IntervalSet() & IntervalSet([(1, 5)])) == []


class TestDifference:
    def test_basic(self):
        a = IntervalSet([(0, 10)])
        b = IntervalSet([(3, 5)])
        assert list(a - b) == [(0, 3), (5, 10)]

    def test_no_overlap(self):
        a = IntervalSet([(0, 10)])
        b = IntervalSet([(20, 30)])
        assert list(a - b) == [(0, 10)]

    def test_full_remove(self):
        a = IntervalSet([(0, 10)])
        b = IntervalSet([(0, 10)])
        assert list(a - b) == []

    def test_multi_cut(self):
        a = IntervalSet([(0, 20)])
        b = IntervalSet([(3, 5), (10, 12), (15, 17)])
        assert list(a.difference(b)) == [(0, 3), (5, 10), (12, 15), (17, 20)]

    def test_type_error_method(self):
        with pytest.raises(TypeError):
            IntervalSet([(1, 5)]).difference([1, 2, 3])

    def test_operator_not_implemented(self):
        with pytest.raises(TypeError):
            _ = IntervalSet([(1, 5)]) - [1, 2, 3]

    def test_operators_type_check(self):
        with pytest.raises(TypeError):
            _ = IntervalSet([(1, 5)]) | []
        with pytest.raises(TypeError):
            _ = IntervalSet([(1, 5)]) & []


# ---- equality ----------------------------------------------------------

class TestEquality:
    def test_equal(self):
        a = IntervalSet([(1, 3), (3, 5)])
        b = IntervalSet([(1, 5)])
        assert a == b

    def test_not_equal(self):
        a = IntervalSet([(1, 3)])
        b = IntervalSet([(1, 4)])
        assert a != b

    def test_not_equal_other_type(self):
        a = IntervalSet([(1, 3)])
        assert a != []
        assert a != None  # noqa: E711

    def test_equal_empty(self):
        assert IntervalSet() == IntervalSet()


# ---- hashability -------------------------------------------------------

class TestHash:
    def test_not_hashable(self):
        with pytest.raises(TypeError):
            hash(IntervalSet())


# ---- normalization invariants ------------------------------------------

class TestNormalization:
    def test_touching_always_merged(self):
        s = IntervalSet([(0, 2), (2, 4), (4, 6)])
        assert list(s) == [(0, 6)]

    def test_add_touching_merged(self):
        s = IntervalSet([(0, 3)])
        s.add(3, 6)
        assert len(s) == 1
        assert list(s) == [(0, 6)]

    def test_remove_preserves_normalization(self):
        s = IntervalSet([(0, 10), (10, 20)])
        # The constructor merges touching, so s is [(0, 20)]
        assert list(s) == [(0, 20)]
        s.remove(9, 11)
        assert list(s) == [(0, 9), (11, 20)]

    def test_invariant_no_touching(self):
        s = IntervalSet()
        s.add(0, 1)
        s.add(1, 2)
        assert len(s) == 1

    def test_invariant_no_overlap(self):
        s = IntervalSet([(0, 5), (3, 8)])
        assert list(s) == [(0, 8)]


# ---- performance / stress ----------------------------------------------

class TestStress:
    def test_many_adds(self):
        s = IntervalSet()
        for i in range(50_000):
            s.add(i * 2, i * 2 + 1)
        # all adjacent → single interval [0, 50000)
        assert len(s) == 1
        assert list(s) == [(0, 50_000)]

    def test_many_disjoint(self):
        s = IntervalSet()
        for i in range(10_000):
            s.add(i * 3, i * 3 + 1)
        assert len(s) == 10_000

    def test_alternating_add_remove(self):
        s = IntervalSet()
        for i in range(5000):
            s.add(i, i + 1)
        for i in range(0, 5000, 2):
            s.remove(i, i + 1)
        # every even point removed → 2500 intervals of length 1
        assert len(s) == 2500

    def test_total_length_after_ops(self):
        s = IntervalSet()
        s.add(0, 1000)
        s.remove(200, 300)
        s.remove(500, 600)
        assert s.total_length() == 800

    def test_contains_large_set(self):
        s = IntervalSet()
        for i in range(20_000):
            s.add(i * 10, i * 10 + 5)
        assert s.contains(25)
        assert not s.contains(25_0000)

    def test_union_large(self):
        a = IntervalSet()
        b = IntervalSet()
        for i in range(5000):
            a.add(i * 4, i * 4 + 1)
            b.add(i * 4 + 2, i * 4 + 3)
        c = a | b
        # a has 5000 intervals, b has 5000, gap of 1 between each pair
        assert len(c) == 10_000

    def test_difference_large(self):
        a = IntervalSet([(0, 100_000)])
        b = IntervalSet()
        for i in range(1000):
            b.add(i * 100, i * 100 + 50)
        c = a - b
        assert c.total_length() == 100_000 - 50_000

    def test_intersection_large(self):
        a = IntervalSet([(0, 100_000)])
        b = IntervalSet([(50, 60), (100, 200), (50000, 60000)])
        c = a & b
        assert list(c) == [(50, 60), (100, 200), (50000, 60000)]


